import math


def summarize_readings(channel, readings):
    if not isinstance(channel, str) or not channel:
        raise ValueError("invalid channel")
    if not isinstance(readings, list):
        raise ValueError("readings must be a list")
    points = []
    seen = set()
    for reading in readings:
        if not isinstance(reading, dict) or set(reading) != {"day", "value"}:
            raise ValueError("invalid reading")
        day = reading["day"]
        value = reading["value"]
        if isinstance(day, bool) or not isinstance(day, int) or not 1 <= day <= 7 or day in seen:
            raise ValueError("invalid day")
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
            raise ValueError("invalid value")
        seen.add(day)
        points.append({"day": day, "value": value})
    points.sort(key=lambda point: point["day"])
    if len(points) < 2 or points[0]["value"] == 0:
        change = None
    else:
        first = points[0]["value"]
        change = (points[-1]["value"] - first) / first * 100
    return {"channel": channel, "points": points, "percent_change": change}

